-- Migration: **`schedule_baseline_tasks`**. One task's row in a schedule baseline (SC-3): its title and, when it was schedulable then, its early start, early finish, working duration and total float. A task that could not be scheduled is kept with null dates and the reason, so it is neither lost nor given a date it never had. Append-only.

CREATE TABLE IF NOT EXISTS "schedule_baseline_tasks" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "baseline_pid" uuid NOT NULL, "task_pid" uuid NOT NULL, "title" varchar NOT NULL, "start_date" date NULL, "finish_date" date NULL, "duration_days" integer NULL, "total_float" integer NULL, "unscheduled_reason" varchar NULL );

CREATE UNIQUE INDEX schedule_baseline_tasks_once ON schedule_baseline_tasks (baseline_pid, task_pid);
